message.content:
{
  "title": "The Ruin's Price",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined royal city.",
      "visual_description": "A party of four stands on a hill overlooking a vast broken city. Crumbled towers, torn royal banners flapping in the wind, and a dim glow from the central castle.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 2,
      "caption": "They pass through the broken outer gates.",
      "visual_description": "The massive iron gates lie twisted on the ground. Kaelen touches the rusted metal while Mira scouts ahead; Thorn and Nari watch the shadows between collapsed buildings.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 3,
      "caption": "Townspeople whisper warnings from doorways.",
      "visual_description": "Huddled figures in rags peek from shattered doorways, gesturing for the party to leave. One old woman points toward the central castle and shakes her head.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Old Woman"]
    },
    {
      "scene_number": 4,
      "caption": "Armored patrols march through the square.",
      "visual_description": "Three hulking guards in dark plate armor stride across a cracked marble square, their helmets hiding faces. The party hides behind a fallen statue of a king.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Patrol Guard 1", "Patrol Guard 2", "Patrol Guard 3"]
    },
    {
      "scene_number": 5,
      "caption": "Mira reads a cryptic map in a ruined chapel.",
      "visual_description": "Inside a roofless chapel, Mira unrolls a glowing map on an altar. Thorn peers over her shoulder while Kaelen watches the doorway and Nari traces lines on the floor.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 6,
      "caption": "They find a cursed tower with a whispering door.",
      "visual_description": "A spiraling black tower looms before them. Its door is carved with faces that murmur promises of power. The party hesitates as the whispers grow louder.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 7,
      "caption": "Nari resists the door's temptation with magic.",
      "visual_description": "Nari raises a glowing hand and speaks a counter-charm. The whispers fade, the faces go silent, and the door creaks open to reveal a dark staircase.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 8,
      "caption": "Climbing the tower, they see a dragon's silhouette.",
      "visual_description": "Through a broken window, a massive winged shadow glides past the moon. Thorn gasps and steps back; the others freeze, watching the dragon circle the castle.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 9,
      "caption": "They reach the treasure room at the top.",
      "visual_description": "A circular chamber filled with gold, gems, and a single ornate chest. The air shimmers with enchantment. Kaelen moves toward the chest, entranced.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 10,
      "caption": "Mira spots the real path behind a false wall.",
      "visual_description": "Mira ignores the treasure and presses a loose stone. A section of wall slides away, revealing a narrow passage. She calls the others, snapping Kaelen from his trance.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari"]
    },
    {
      "scene_number": 11,
      "caption": "The passage leads to a dungeon beneath the castle.",
      "visual_description": "Damp stone corridors lit by flickering torches. Cells line the walls. In one, a prisoner in rags lifts his head—their rescue target, Prince Aldric.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    },
    {
      "scene_number": 12,
      "caption": "Kaelen picks the lock while Mira keeps watch.",
      "visual_description": "Kaelen kneels at the cell door, working small tools into the lock. Mira stands with bow drawn, listening for footsteps. Thorn and Nari help the prince stand.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    },
    {
      "scene_number": 13,
      "caption": "Guards discover them; a fight breaks out.",
      "visual_description": "Three patrol guards round the corner. Thorn shoves the prince behind him and draws a sword. Mira fires an arrow as Kaelen finishes the lock. Nari readies a spell.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric", "Patrol Guard 1", "Patrol Guard 2", "Patrol Guard 3"]
    },
    {
      "scene_number": 14,
      "caption": "They escape into the courtyard under moonlight.",
      "visual_description": "The party bursts through a door into a moonlit courtyard. Rubble and broken statues scatter the area. The dragon's silhouette passes overhead again, closer now.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    },
    {
      "scene_number": 15,
      "caption": "A magic door blocks the exit path.",
      "visual_description": "A shimmering portal of blue energy bars the way to the outer gate. It pulses with runes. Nari steps forward to analyze it while the others guard her.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    },
    {
      "scene_number": 16,
      "caption": "Nari dispels the magic door with a ritual.",
      "visual_description": "Nari traces glowing symbols in the air. The runes on the door flare and then fade, the portal dissolving into sparks. The path ahead clears.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the crumbling bridge.",
      "visual_description": "A stone bridge spans a deep chasm, cracked and missing sections. The party runs, leaping gaps as stones fall behind them. The dragon roars in the distance.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side as the bridge collapses.",
      "visual_description": "The last stone crumbles as Kaelen pulls the prince onto solid ground. The bridge falls into the chasm. Beyond, the open road stretches toward safety, the ruined city behind them.",
      "characters": ["Kaelen", "Mira", "Thorn", "Nari", "Prince Aldric"]
    }
  ]
}

